/*
	Coding in unusual places: from the balcony // 3.6.2023
	#minacoding #p5js #generativeart
	issue: screen not getting complete white over time
 */

let img, scl;

function preload() {
	// preload() runs once
	img = loadImage('https://openprocessing.org/sketch/1946676/files/balcony.jpg.jpg');
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	pixelDensity(1);
	frameRate(60);
	scl = max(width / img.width, height / img.height);

	// set alpha of the image
  let imgMaxIndex = 4 * (img.width) * (img.height);
	img.loadPixels();
	for (let i = 0; i < imgMaxIndex; i+=4) {
    img.pixels[i + 3] = 32;
  }
  img.updatePixels();
}

function windowResized() {
	setup();
}

function draw() {
	background(255, 1);

	if (frameCount % 10 === 0) {
		const ts = 80;
		const sx = floor(random(img.width/ts))
		const sy = floor(random(img.height/ts))
		// image(img, 0, 0, img.width * scl, img.height * scl);
		image(img, sx * ts * scl, sy * ts * scl, ts * scl, ts *scl, sx * ts, sy * ts, ts, ts);
	}

	for (let i = 0; i < 60; i++) {
		const x = floor(random(img.width));
		const y = floor(random(img.height));
		let source = img.get(x, y);
		let sourcealpha = color(source[0], source[1], source[2], 32);
		stroke(sourcealpha);
		strokeWeight(20);
		point(x * scl, y * scl);
		stroke(source);
		strokeWeight(floor(random(1, 10)));
		point(x * scl, y * scl);
	}
	// // noLoop() removed for animation
}
